import{_ as e,o as n,c as t,a3 as s}from"./chunks/framework.DxEvSMU4.js";const g=JSON.parse('{"title":"P1 問自己的文件","description":"","frontmatter":{},"headers":[],"relativePath":"examples/p1-docs-qa.md","filePath":"examples/p1-docs-qa.md","lastUpdated":1793035196000}'),i={name:"examples/p1-docs-qa.md"};function l(o,a,r,d,p,c){return n(),t("div",null,[...a[0]||(a[0]=[s(`<h1 id="p1-問自己的文件" tabindex="-1">P1 問自己的文件 <a class="header-anchor" href="#p1-問自己的文件" aria-label="Permalink to &quot;P1 問自己的文件&quot;">​</a></h1><div class="info custom-block"><p class="custom-block-title">本章屬性</p><ul><li>等級: ○ 依情境</li><li>狀態: 可閱讀 (部分資料待核對)</li><li>資料基準日: 2026-10-26</li><li>待查證: 設定步驟與指令依 Open WebUI 官方文件整理, 未實機驗證; Open WebUI 的選單名稱會隨版本調整, 操作前請以所用版本的文件核對; 繁體中文的切塊大小與 Top K 建議值尚無公開實測; 嵌入模型範例已更換, 數字須對照官方模型卡; 文中的類比為整理者所寫, 不代表技術上完全等同</li></ul></div><p><strong>結論</strong>: 個人只要組到里程碑 1 (M0 至 M2), 再加上 M4 的檢索功能, 就能把筆記, 手冊與論文放進 Open WebUI (在瀏覽器裡和模型對話的使用者介面, 內建知識庫功能) 的知識庫, 用自然語言提問並取得附出處的回答. 不需要閘道, 身分驗證或代理. 上線前用 M4.3 節的 50 題自測法確認檢索命中率, 之後每次換模型或調整設定都重跑一次.</p><p><strong>對象</strong>: 個人. <strong>需要的模組</strong>: M1, M2, M4.</p><div class="tip custom-block"><p class="custom-block-title">本頁常見名詞</p><table tabindex="0"><thead><tr><th>詞</th><th>意思</th></tr></thead><tbody><tr><td>里程碑 (milestone)</td><td>本手冊把組裝分成三個階段, 每個階段結束時系統都能獨立使用; 定義見<a href="/lanai-handbook/build/overview">組裝總覽</a></td></tr><tr><td>知識庫 (knowledge)</td><td>Open WebUI 裡存放文件的地方, 文件放進去後會整理成可搜尋的段落</td></tr><tr><td>檢索增強生成 (Retrieval-Augmented Generation, RAG)</td><td>先從文件找出相關段落, 再把段落連同問題交給模型回答的做法</td></tr><tr><td>嵌入模型 (embedding model) 與向量</td><td>嵌入模型把一段文字轉成一串數字, 這串數字稱為向量; 意思相近的段落, 向量也相近</td></tr><tr><td>切塊 (chunk)</td><td>把長文件切成較短的段落, 檢索時以段落為單位</td></tr><tr><td>Top K</td><td>每次提問時取回最相關的前幾段 (K 段)</td></tr><tr><td>Docker 與資料卷 (volume)</td><td>Docker 把程式和它需要的環境包成容器執行; 資料卷是容器存放資料的位置, 容器重建時資料仍會保留</td></tr><tr><td>127.0.0.1</td><td>代表「這台電腦自己」的網址; 服務只綁這個位址時, 其他電腦連不進來</td></tr></tbody></table><p>完整詞彙見<a href="/lanai-handbook/ref/glossary">術語對照</a>.</p></div><h2 id="情境" tabindex="-1">情境 <a class="header-anchor" href="#情境" aria-label="Permalink to &quot;情境&quot;">​</a></h2><p>讀者手上累積了數百份文件: 工作手冊, 會議簡報, 研究論文, 個人筆記. 原本找資料的方式是在資料夾裡用檔名搜尋, 或打開檔案逐一按 Ctrl+F. 這種做法有兩個限制: 關鍵字必須和原文一模一樣才找得到, 而且答案常分散在好幾份文件裡. 把文件上傳到雲端 AI 服務可以解決搜尋問題, 但私人筆記或工作文件不一定適合離開自己的電腦.</p><p>本範例的做法可以想成「替自己的書架請一位圖書館員」: 先把文件交給系統整理成可搜尋的段落, 之後用一般說話的方式提問, 系統找出最相關的幾段原文, 再請模型根據這幾段原文回答, 並列出答案出自哪份文件. 文件, 索引與模型都留在本機.</p><h2 id="需要的模組" tabindex="-1">需要的模組 <a class="header-anchor" href="#需要的模組" aria-label="Permalink to &quot;需要的模組&quot;">​</a></h2><table tabindex="0"><thead><tr><th>模組</th><th>里程碑</th><th>在本範例的用途</th></tr></thead><tbody><tr><td><a href="/lanai-handbook/build/m0-foundation">M0 基礎環境</a></td><td>里程碑 1</td><td>一台 Linux 或 Mac 加 Docker 即可; 設定資料卷的備份</td></tr><tr><td><a href="/lanai-handbook/build/m1-inference">M1 推論伺服器</a></td><td>里程碑 1</td><td>以 Ollama 執行對話模型與嵌入模型; Ollama 是載入模型並提供 API 的推論伺服器</td></tr><tr><td><a href="/lanai-handbook/build/m2-ui-proxy">M2 使用者介面與反向代理</a></td><td>里程碑 1</td><td>Open WebUI 只綁 127.0.0.1, 單人使用不需要反向代理</td></tr><tr><td><a href="/lanai-handbook/build/m4-retrieval">M4 檢索 (RAG)</a></td><td>里程碑 2 的模組</td><td>知識庫, Docling (把 PDF, Word 等檔案轉成純文字的解析服務), 嵌入模型; 個人使用可以只加 M4, 不必組 M3, M5, M6</td></tr><tr><td><a href="/lanai-handbook/build/m6-observability">M6 可觀測, 稽核與評估</a> (只用 M6.1 節)</td><td>里程碑 2 的模組</td><td>保存 50 題測試集, 不需要追蹤平台</td></tr></tbody></table><p>硬體等級 A 與 C (16GB) 的讀者, <a href="/lanai-handbook/build/overview">組裝總覽</a>建議改用 AnythingLLM 桌面版, 這是把對話介面, 知識庫與模型呼叫包在同一個程式裡的桌面應用程式; 本頁以 Open WebUI 說明, 概念相同.</p><h2 id="流程" tabindex="-1">流程 <a class="header-anchor" href="#流程" aria-label="Permalink to &quot;流程&quot;">​</a></h2><p>整個流程分成兩段. 第一段是匯入: 系統把文件轉成文字, 切成段落, 再替每個段落算出向量存起來, 這一步只在新增文件時做. 第二段是提問: 系統把問題也轉成向量, 找出最接近的幾段原文, 交給對話模型寫出回答. 下圖的箭頭表示資料往哪裡送.</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark-dimmed vp-code" tabindex="0"><code><span class="line"><span>匯入文件 (一次性, 之後有新文件再補)</span></span>
<span class="line"><span></span></span>
<span class="line"><span>[讀者電腦上的文件資料夾: PDF, Word, Markdown]</span></span>
<span class="line"><span>      | 在瀏覽器上傳 (Workspace &gt; Knowledge &gt; Add Content)</span></span>
<span class="line"><span>      v</span></span>
<span class="line"><span>[Open WebUI] --HTTP (Docker 內部網路)--&gt; [docling-serve]</span></span>
<span class="line"><span>      |          &lt;-- 解析後的文字與表格</span></span>
<span class="line"><span>      | 切成段落 (chunk)</span></span>
<span class="line"><span>      v</span></span>
<span class="line"><span>[Ollama 嵌入模型] --&gt; 每段轉成向量 --&gt; [Open WebUI 內建向量庫]</span></span>
<span class="line"><span></span></span>
<span class="line"><span>提問 (每次)</span></span>
<span class="line"><span></span></span>
<span class="line"><span>[讀者的瀏覽器] --http://127.0.0.1:3000--&gt; [Open WebUI]</span></span>
<span class="line"><span>      | 1. 問題轉成向量, 在知識庫找出最相關的 K 段</span></span>
<span class="line"><span>      | 2. 問題 + K 段原文 + 提示範本, 送給對話模型</span></span>
<span class="line"><span>      v</span></span>
<span class="line"><span>[Ollama 對話模型]</span></span>
<span class="line"><span>      | 回答 + 出處 (文件名稱與段落)</span></span>
<span class="line"><span>      v</span></span>
<span class="line"><span>[讀者] --&gt; 點開出處, 和原文核對</span></span></code></pre></div><p>資料只在本機的三個地方流動: 文件資料夾, Open WebUI 的資料卷 (含向量庫), 以及 Ollama. 沒有任何連接埠對外開放.</p><h2 id="設定要點" tabindex="-1">設定要點 <a class="header-anchor" href="#設定要點" aria-label="Permalink to &quot;設定要點&quot;">​</a></h2><p>以下依 Open WebUI 與 Ollama 官方文件整理, 未實機驗證.</p><p><strong>1. 啟動 Docling 解析服務.</strong> Docling 負責把 PDF, Word 這類檔案轉成純文字與表格, 模型才讀得到內容. Open WebUI 官方文件提供的 CPU 版映像為 <code>quay.io/docling-project/docling-serve</code>, 服務埠為 5001; NVIDIA 顯示卡另有 <code>docling-serve-cu128</code> 映像. 依 M2.2 節的建議, 讓 Docling 與 Open WebUI 共用同一個 Docker 網路, 不發布 Docling 的連接埠. 下列指令先建立名為 <code>localai</code> 的內部網路, 再在這個網路裡啟動 Docling:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark-dimmed vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#F69D50;">docker</span><span style="--shiki-light:#032F62;--shiki-dark:#96D0FF;"> network</span><span style="--shiki-light:#032F62;--shiki-dark:#96D0FF;"> create</span><span style="--shiki-light:#032F62;--shiki-dark:#96D0FF;"> localai</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#F69D50;">docker</span><span style="--shiki-light:#032F62;--shiki-dark:#96D0FF;"> run</span><span style="--shiki-light:#005CC5;--shiki-dark:#6CB6FF;"> -d</span><span style="--shiki-light:#005CC5;--shiki-dark:#6CB6FF;"> --name</span><span style="--shiki-light:#032F62;--shiki-dark:#96D0FF;"> docling</span><span style="--shiki-light:#005CC5;--shiki-dark:#6CB6FF;"> --network</span><span style="--shiki-light:#032F62;--shiki-dark:#96D0FF;"> localai</span><span style="--shiki-light:#005CC5;--shiki-dark:#F47067;"> \\</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#96D0FF;">  quay.io/docling-project/docling-serve:</span><span style="--shiki-light:#D73A49;--shiki-dark:#F47067;">&lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#96D0FF;">固定版本標</span><span style="--shiki-light:#24292E;--shiki-dark:#ADBAC7;">籤</span><span style="--shiki-light:#D73A49;--shiki-dark:#F47067;">&gt;</span></span></code></pre></div><p>Open WebUI 的容器同樣加上 <code>--network localai</code> (其餘參數見 M2.2 節). 官方文件提醒, 除非另外設定 Redis (讓多個行程共用狀態的記憶體資料庫) 這類共享狀態機制, 否則 docling-serve 維持 <code>UVICORN_WORKERS=1</code>.</p><p><strong>2. 在 Open WebUI 指定文件解析引擎.</strong> 到 <strong>Settings &gt; Admin &gt; Documents</strong>, 把內容解析引擎 (Content Extraction Engine) 設為 <strong>Docling</strong>, Docling Server URL 填 <code>http://docling:5001</code> (這也是官方預設值). 處理掃描檔或圖片時, Docling 會用到 OCR 引擎; 預設的自動選擇與改指定其他引擎的方式見 <a href="/lanai-handbook/build/m4-retrieval">M4.1 節</a>與 M4.5 節. 上傳第一份文件後, 先預覽解析出的文字; 官方疑難排解頁指出, 模型「看不到」文件內容通常是解析問題, 而不是模型問題.</p><p><strong>3. 設定嵌入模型.</strong> 嵌入模型決定系統如何判斷「兩段文字意思接近」, 可以想成替每個段落在一張意思地圖上標座標, 提問時找座標最近的段落. 同一頁的嵌入設定選 Ollama, 模型例如 <code>embeddinggemma</code> 或 <code>nomic-embed-text-v2-moe</code> (Ollama 模型庫的標籤). 兩者的取捨見 M4.2 節. EmbeddingGemma 約 300M 參數, 上下文 2,048 token, 預設標籤的檔案大小為 622MB, 授權為 Gemma Terms of Use; nomic-embed-text-v2-moe 總參數 475M, 每次運算啟用 305M, 上下文 512 token, Ollama 標籤的檔案大小為 958MB, 授權為 Apache 2.0 (來源: 各模型的 Hugging Face 模型卡, Ollama 模型庫標籤頁). nomic-embed-text-v2-moe 的模型卡要求查詢與文件分別加上 <code>search_query:</code> 與 <code>search_document:</code> 前綴; 介面無法設定前綴時, 優先選 EmbeddingGemma (推論, 信心: 中). 多語言支援範圍請以模型卡為準: EmbeddingGemma 模型卡寫明訓練資料涵蓋 100 多種口說語言, nomic-embed-text-v2-moe 模型卡標示約 100 種語言; 兩者對繁體中文的表現都須用 M4.3 節的自建測試集確認. 官方文件說明, 更換嵌入模型後必須重建所有知識庫的索引, 不同模型產生的向量不能混用.</p><p><strong>4. 調整切塊與檢索數量.</strong> 切塊大小決定每個段落多長, 重疊 (overlap) 讓相鄰段落共用一小段文字, 避免一句話剛好斷在兩段之間; Top K 決定每次取回幾段交給模型. 官方疑難排解頁對「本機模型, 上下文 8K 以內」的建議是 Chunk Size 1000, Chunk Overlap 100, Top K 3 至 5. 同一頁也指出, Ollama 在顯示記憶體小於 24GiB 時預設上下文只有 4096 token, 建議到 <strong>Settings &gt; Admin &gt; Models</strong> 的 Advanced Params 把對話模型的上下文長度調到至少 8192. 這些值以英文文件為基礎, 繁體中文的最佳值請用 M4.3 節的測試比較 (推論, 信心: 中).</p><p><strong>5. 建立知識庫.</strong> 到 <strong>Workspace &gt; Knowledge</strong> 建立知識庫, 用 <strong>Add Content</strong> 上傳檔案或整個資料夾. 官方文件另有 <strong>Sync directory</strong> 功能, 可以增量同步本機資料夾. 建議依主題分成幾個知識庫 (例如「工作手冊」「研究論文」), 方便提問時指定範圍.</p><p><strong>6. 提問時指定知識庫.</strong> 在對話框輸入 <code>#</code> 選擇知識庫; 或到 <strong>Workspace &gt; Models &gt; Edit</strong> 建立一個專用模型 (例如「我的文件助理」) 並附加知識庫. 官方文件說明, 模型若沒有限定知識庫, 會搜尋該使用者可存取的所有知識.</p><p><strong>7. 提示範本.</strong> 提示範本是系統每次附在問題前面, 交給模型的固定說明, 檢索到的段落會填進範本裡的指定位置. 在 <strong>Settings &gt; Admin &gt; Documents</strong> 可以改寫 RAG 範本. 官方文件規定以 CONTEXT 佔位符 (以兩層大括號包住, 寫法見下方範例) 標示檢索內容的位置; 不要加 QUERY 佔位符, 因為使用者的問題會自動附在後面, 加了會重複出現. 範例:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark-dimmed vp-code" tabindex="0"><code><span class="line"><span>請只根據下列參考資料回答問題, 使用繁體中文.</span></span>
<span class="line"><span>規則:</span></span>
<span class="line"><span>1. 每個重點後面標出出處 (文件名稱).</span></span>
<span class="line"><span>2. 參考資料沒有提到的內容, 回答「文件中沒有相關內容」, 不要自行補充.</span></span>
<span class="line"><span>3. 不同文件說法不一致時, 分別列出並註明出處.</span></span>
<span class="line"><span></span></span>
<span class="line"><span>參考資料:</span></span>
<span class="line"><span>{{CONTEXT}}</span></span></code></pre></div><p>這份範本只在系統事先把檢索內容放進對話時才有作用. Open WebUI 文件說明, 模型的函式呼叫 (Function Calling) 設為 Legacy 時, 掛在模型或資料夾上的知識庫會在回答前先檢索並放進對話; 設為 Default 或 Native 時則不會事先放入, 改由模型自己決定要不要呼叫內建的知識庫查詢工具. 採用後者時, 要在系統提示中要求模型「回答前先查知識庫」, 驗收時兩種設定都測一次 (來源: Open WebUI 文件 Retrieval Augmented Generation).</p><p><strong>8. 環境變數只在第一次啟動時生效.</strong> Open WebUI 文件中標為 <code>ConfigVar</code> 的環境變數, 第一次啟動後會存入內部設定; 之後再改環境變數不會生效, 須改在管理介面調整.</p><h2 id="驗收方式" tabindex="-1">驗收方式 <a class="header-anchor" href="#驗收方式" aria-label="Permalink to &quot;驗收方式&quot;">​</a></h2><p>依 M4.3 節的 50 題自測法, 加上回答層級的檢查:</p><ol><li><strong>檢索命中率</strong>: 從自己的文件挑 50 個實際會問的問題, 每題記下正確答案所在的文件與段落. 逐題提問, 檢查回答附的出處是否包含正確段落 (前 K 段內出現即算命中). 若要比較兩個嵌入模型, 依 M4.3 節分別建立知識庫, 命中率差距小於 5 個百分點時選記憶體較小者.</li><li><strong>找不到的問題</strong>: 另加 5 題文件中確定沒有答案的問題, 回答應該是「文件中沒有相關內容」, 而不是編出一個答案.</li><li><strong>出處核對</strong>: 從 50 題中抽 10 題, 點開出處和原文逐句核對, 確認回答沒有扭曲原意.</li><li><strong>解析檢查</strong>: 挑 3 份具代表的文件 (含表格的 PDF, 掃描檔, 長篇 Word), 預覽解析結果, 確認沒有整段遺漏.</li><li><strong>保存基準</strong>: 把 50 題與當次命中率存進 M6.1 節的測試集. 通過門檻由讀者自訂; 本手冊建議至少不低於第一次測得的基準值, 之後每次換模型, 換嵌入模型或調整切塊都重跑 (推論).</li></ol><h2 id="風險與限制" tabindex="-1">風險與限制 <a class="header-anchor" href="#風險與限制" aria-label="Permalink to &quot;風險與限制&quot;">​</a></h2><table tabindex="0"><thead><tr><th>風險</th><th>影響</th><th>因應方式</th></tr></thead><tbody><tr><td>文件內容變成兩份</td><td>原始檔之外, Open WebUI 的資料卷也保存了解析後的文字與向量, 備份檔同樣含有文件內容</td><td>資料卷納入 M0 的備份, 備份檔加密保存; 刪除原始檔時一併從知識庫移除</td></tr><tr><td>模型回答錯誤或扭曲原意</td><td>讀者若直接引用, 可能把錯誤帶進工作文件</td><td>提示範本要求標出處; 重要結論一律點開出處核對原文</td></tr><tr><td>檢索沒找到正確段落</td><td>模型只能根據錯誤段落回答, 看起來仍然很流暢</td><td>用 50 題自測找出弱點; 調整切塊, Top K 或改用其他嵌入模型</td></tr><tr><td>文件中夾帶指令 (間接提示注入)</td><td>從網路下載的文件可能藏有誘導模型的文字 (OWASP LLM01 提示注入, LLM05 資料與模型投毒; 見 K6.4 節)</td><td>只匯入可信來源的文件; 本範例不給模型任何工具, 影響限於回答內容</td></tr><tr><td>上下文不足</td><td>Ollama 預設上下文較短時, 超出長度的檢索段落會遺失</td><td>依設定要點第 4 點調高上下文長度, 並以測試題確認</td></tr><tr><td>介面帳號</td><td>其他人若能登入介面, 就能查詢所有知識庫</td><td>依 M2 只綁 127.0.0.1, 設管理者密碼並關閉公開註冊</td></tr></tbody></table><p>需要人工確認的步驟只有一個: 讀者把回答用在重要決定或對外文件之前, 先核對出處原文.</p><h2 id="參考來源" tabindex="-1">參考來源 <a class="header-anchor" href="#參考來源" aria-label="Permalink to &quot;參考來源&quot;">​</a></h2><ul><li><a href="https://docs.openwebui.com/features/workspace/knowledge" target="_blank" rel="noreferrer">Open WebUI 文件: Knowledge</a></li><li><a href="https://docs.openwebui.com/features/chat-conversations/rag/document-extraction/docling" target="_blank" rel="noreferrer">Open WebUI 文件: Docling Document Extraction</a></li><li><a href="https://docs.openwebui.com/features/chat-conversations/rag" target="_blank" rel="noreferrer">Open WebUI 文件: Retrieval Augmented Generation (RAG)</a></li><li><a href="https://docs.openwebui.com/troubleshooting/rag" target="_blank" rel="noreferrer">Open WebUI 文件: RAG 疑難排解</a></li><li><a href="https://docs.openwebui.com/reference/env-configuration" target="_blank" rel="noreferrer">Open WebUI 文件: Environment Variable Configuration</a></li><li><a href="https://ollama.com/library/embeddinggemma/tags" target="_blank" rel="noreferrer">Ollama 模型庫: embeddinggemma 標籤頁</a></li><li><a href="https://ollama.com/library/nomic-embed-text-v2-moe/tags" target="_blank" rel="noreferrer">Ollama 模型庫: nomic-embed-text-v2-moe 標籤頁</a></li><li><a href="https://huggingface.co/google/embeddinggemma-300m" target="_blank" rel="noreferrer">Hugging Face: google/embeddinggemma-300m</a></li><li><a href="https://huggingface.co/nomic-ai/nomic-embed-text-v2-moe" target="_blank" rel="noreferrer">Hugging Face: nomic-ai/nomic-embed-text-v2-moe</a></li><li>站內: <a href="/lanai-handbook/build/m4-retrieval">M4 檢索 (RAG)</a>, <a href="/lanai-handbook/build/m2-ui-proxy">M2 使用者介面與反向代理</a>, <a href="/lanai-handbook/know/k6-security">K6 安全基礎與風險控管</a></li><li>文中的類比 (圖書館員, 意思地圖): 整理者所寫, 無外部來源, 不應當作技術定義引用.</li></ul>`,37)])])}const m=e(i,[["render",l]]);export{g as __pageData,m as default};
